@startuml

class Bus {
  + LicensePlateNumber : string
  + InRepairShop : boolean
}

class Driver {
  + Name : string
  + ID : int
  + OnSickLeave : boolean
}

class Route {
  + RouteNumber : int
}

class Shift {
  + ShiftType : string
  + Date : date
}

class BusOnRoute {
  + Bus : Bus
  + Route : Route
  + Shift : Shift
}

Bus "1" -- "*" BusOnRoute
Driver "1" -- "*" BusOnRoute
Route "1" -- "*" BusOnRoute

@enduml

